def test_barbed_bloodletter():
    """Barbed Bloodletter: ETB trigger emits one of ['COUNTER_ADDED', 'DAMAGE', 'PT_MODIFICATION', 'TEMPORARY_EFFECT']."""
    game, p1, p2 = _new_game_with_two_players()
    _seed_board(game, p1, p2)
    card = _create_in_hand(game, p1, 'Barbed Bloodletter')
